// Resume as conversas do Teams: com quem é, a última mensagem e quando (horário de Brasília).
// Filtra pelo nome da pessoa ou do grupo (busca) e devolve as mais recentes primeiro.
const entrada = $('Quando a Kira usar o Teams').first().json;
const normalizar = (s) => String(s ?? '').toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();
const textoDe = (html) =>
  String(html ?? '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
const quando = (iso) => (iso ? DateTime.fromISO(iso).setZone('America/Sao_Paulo').toFormat('dd/MM HH:mm') : '');
const TIPOS = { oneOnOne: 'individual', group: 'grupo', meeting: 'reunião' };

const chats = $input.first().json.value ?? [];
// O dono aparece em todas as conversas: é o participante mais frequente.
const contagem = new Map();
for (const c of chats) for (const m of c.members ?? []) if (m.userId) contagem.set(m.userId, (contagem.get(m.userId) ?? 0) + 1);
const dono = chats.length > 1 ? [...contagem.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] : null;

const busca = normalizar(entrada.busca);
const quantidade = Math.min(Math.max(Number(entrada.quantidade) || 10, 1), 30);
const conversas = chats
  .map((c) => {
    const todas = (c.members ?? []).filter((m) => m.userId !== dono).map((m) => m.displayName).filter(Boolean);
    const pessoas = todas.length > 8 ? [...todas.slice(0, 8), `e mais ${todas.length - 8}`] : todas;
    const ultima = c.lastMessagePreview ?? null;
    return {
      chat_id: c.id,
      tipo: TIPOS[c.chatType] ?? c.chatType,
      nome: c.topic || (todas.length > 4 ? `${todas.slice(0, 4).join(', ')} e mais ${todas.length - 4}` : todas.join(', ')) || '(sem nome)',
      pessoas,
      todas,
      ultima_mensagem: ultima?.body
        ? { de: ultima.from?.user?.displayName ?? '', quando: quando(ultima.createdDateTime), texto: textoDe(ultima.body.content).slice(0, 200) }
        : null,
      data: ultima?.createdDateTime ?? c.lastUpdatedDateTime ?? '',
    };
  })
  .filter((c) => !busca || normalizar([c.nome, ...c.todas].join(' ')).includes(busca))
  .sort((a, b) => String(b.data).localeCompare(String(a.data)));

return [{ json: { total: conversas.length, conversas: conversas.slice(0, quantidade).map(({ data, todas, ...c }) => c) } }];

// Resume as mensagens de uma conversa do Teams, da mais antiga para a mais nova.
const entrada = $('Quando a Kira usar o Teams').first().json;
const textoDe = (html) =>
  String(html ?? '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
const quando = (iso) => (iso ? DateTime.fromISO(iso).setZone('America/Sao_Paulo').toFormat('dd/MM HH:mm') : '');

const mensagens = ($input.first().json.value ?? [])
  .filter((m) => m.messageType === 'message' && !m.deletedDateTime)
  .map((m) => ({
    de: m.from?.user?.displayName ?? m.from?.application?.displayName ?? '',
    quando: quando(m.createdDateTime),
    texto: textoDe(m.body?.content).slice(0, 800),
    anexos: (m.attachments ?? []).map((a) => a.name).filter(Boolean),
  }))
  .reverse();

return [{ json: { chat_id: entrada.chat_id, total: mensagens.length, mensagens } }];

// Confere o pedido de envio e monta a mensagem (texto simples vira HTML seguro, com quebras de linha).
const entrada = $('Quando a Kira usar o Teams').first().json;
const chat = String(entrada.chat_id ?? '').trim();
const texto = String(entrada.texto ?? '').trim();
if (!chat) throw new Error('Faltou o id da conversa: use conversas_teams para achar a conversa certa.');
if (!texto) throw new Error('Faltou o texto da mensagem.');
const html = texto.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
return [{ json: { chat_id: chat, corpo: JSON.stringify({ body: { contentType: 'html', content: html } }) } }];

// Resume o erro para a Kira explicar ao dono.
const item = $input.first().json;
const bruto = item.error ?? item;
const textos = [];
const coletar = (valor, profundidade = 0) => {
  if (!valor || profundidade > 4) return;
  if (typeof valor === 'string') {
    textos.push(valor);
    return;
  }
  if (typeof valor === 'object') {
    for (const chave of ['message', 'description']) {
      if (typeof valor[chave] === 'string') textos.push(valor[chave]);
    }
    coletar(valor.error, profundidade + 1);
  }
};
coletar(bruto);
const erro = [...new Set(textos.map((t) => t.trim()).filter(Boolean))].join(' — ').slice(0, 600) || 'erro desconhecido';

return [{ json: { ok: false, erro, orientacao: 'Não deu certo no Teams. Explique o erro ao dono em poucas palavras; nada foi enviado.' } }];
